-- Keep the curriculum exactly at 68 published lessons. Old V29/V30 lesson rows are archived by status rather than hard-deleted.
update public.learning_lessons set content=$${"videoUrl":"","article":"База урока — не отдельный сигнал, а набор принципов, по которым принимается решение. В исходном описании акцент стоит на базовых принципах торговли и на переходе от случайных входов к понятной логике.","examples":"Записанный первый эфир: базовые принципы торговли, сигналы, первые сделки и фундамент дальнейшего обучения.","practice":"Возьми 5 исторических ситуаций и для каждой до открытия сделки запиши: что ты наблюдаешь, какой базовый принцип применяешь и какое условие заставит тебя пропустить вход. Сравни решение с результатом, не меняя исходные правила задним числом.","quiz":[{"id":"q1","type":"single_select","question":"В ситуации по уроку «Первый эфир — базовые принципы торговли» ты получил неоднозначный сигнал. Что разумнее сделать?","options":[{"value":"A","label":"Собрать дополнительное подтверждение перед решением","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Сразу входить","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Увеличить риск","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Игнорировать контекст","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Сначала проверь условия сценария."},{"id":"q2","type":"multi_select","question":"Какие действия превращают материал урока в практический навык?","options":[{"value":"A","label":"Применить идею на истории","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Записать критерии решения","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Проверить спорные случаи","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Считать любой похожий график сигналом","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Ищи проверяемое применение, а не автоматическое распознавание."},{"id":"q3","type":"true_false","question":"Для урока «Первый эфир — базовые принципы торговли» всегда достаточно одного признака, чтобы принять решение без проверки остальных условий.","options":[{"value":"true","label":"Верно","feedback":"Утверждение слишком сильно обобщает идею урока и игнорирует остальные условия."},{"value":"false","label":"Неверно","feedback":"Утверждение соответствует логике урока."}],"correctValues":["false"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Сначала формулируй причину входа, а уже потом нажимай кнопку сделки.","facts":["Сначала формулируй причину входа, а уже потом нажимай кнопку сделки.","Сигнал без объяснимого принципа не превращается в устойчивую систему.","Базовые правила должны быть одинаковыми от сделки к сделке."],"sourceTitle":"Первый эфир — базовые принципы торговли","sourceDuration":"50 минут 7 секунд","lessonFormat":"video","sourceOrder":1,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='basics-first-live';
update public.learning_lessons set content=$${"videoUrl":"","article":"Японская свеча показывает не только направление движения, но и борьбу покупателей и продавцов за выбранный период. Важна форма свечи и её место на графике: одна свеча сама по себе не должна становиться автоматическим сигналом.","examples":"Третий эфир: японские свечи, чтение свечей, настроение рынка, логика входа и домашнее задание.","practice":"На истории выбери 10 свечей в разных контекстах. Для каждой опиши тело, тени, направление предыдущего движения и настроение, которое она может отражать. Затем отдельно отметь 3 случая, где одна свеча сама по себе не даёт основания для входа.","quiz":[{"id":"q1","type":"single_select","question":"После сильного движения появляется свеча с маленьким телом и длинной тенью. Что разумнее сделать первым?","options":[{"value":"C","label":"Игнорировать предыдущие свечи","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Увеличить риск, потому что свеча необычная","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"A","label":"Сразу открыть сделку только по этой свече","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Проверить, что происходило до свечи и как рынок реагирует дальше","feedback":"Выбор согласуется с описанной ситуацией."}],"correctValues":["D"],"hint":"Смотри не на один элемент, а на его место в последовательности движения."},{"id":"q2","type":"multi_select","question":"Какие наблюдения помогут не вырывать одну свечу из контекста?","options":[{"value":"A","label":"Предыдущее движение","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Размер и форма тела/теней","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Реакция следующих свечей","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Только факт цвета свечи","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Сравни несколько элементов последовательности, а не один признак."},{"id":"q3","type":"true_false","question":"Для урока «Свечи, которые дают деньги» всегда достаточно одного признака, чтобы принять решение без проверки остальных условий.","options":[{"value":"true","label":"Верно","feedback":"Утверждение слишком сильно обобщает идею урока и игнорирует остальные условия."},{"value":"false","label":"Неверно","feedback":"Утверждение соответствует логике урока."}],"correctValues":["false"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Смотри на свечу в контексте предыдущего движения.","facts":["Смотри на свечу в контексте предыдущего движения.","Форма свечи помогает оценить настроение рынка, но не заменяет подтверждение.","Логику входа нужно объяснять до открытия сделки."],"sourceTitle":"Свечи, которые дают деньги","sourceDuration":"42 минуты 37 секунд","lessonFormat":"video","sourceOrder":2,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='candles-third-live';
update public.learning_lessons set content=$${"videoUrl":"","article":"Горизонтальный уровень — это область цены, где рынок уже реагировал. Задача анализа не в том, чтобы провести красивую линию, а в том, чтобы найти повторяющуюся реакцию и проверить её контекстом.","examples":"Второй эфир: что такое горизонтальные уровни, как их находить и использовать; в эфире разобраны три сделки.","practice":"Найди 5 горизонтальных уровней и подготовь по каждому сценарий входа. Для каждого укажи, что должно произойти возле уровня, чтобы вход стал оправданным, и что заставит тебя отказаться от сделки.","quiz":[{"id":"q1","type":"single_select","question":"Ты нашёл горизонтальный уровень, но цена подходит к нему на высокой скорости. Что важнее перед входом?","options":[{"value":"C","label":"Размер предыдущей прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Количество сделок за день","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"A","label":"Название уровня","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Наблюдение за реакцией цены в этой области","feedback":"Выбор согласуется с описанной ситуацией."}],"correctValues":["D"],"hint":"Уровень сам по себе не заменяет наблюдение за реакцией."},{"id":"q2","type":"multi_select","question":"При проверке зоны перед решением какие записи полезнее сделать?","options":[{"value":"A","label":"Границы области","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Поведение цены внутри/у области","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Условие отмены сценария","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Только название уровня","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Фиксируй то, что помогает принять и отменить решение."},{"id":"q3","type":"true_false","question":"Один и тот же горизонтальный уровень может требовать разной реакции цены перед решением в разных рыночных ситуациях.","options":[{"value":"true","label":"Верно","feedback":"Утверждение соответствует логике урока."},{"value":"false","label":"Неверно","feedback":"Такой вывод противоречит практической логике урока."}],"correctValues":["true"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Ищи повторные реакции цены, а не одиночное касание.","facts":["Ищи повторные реакции цены, а не одиночное касание.","Уровень должен иметь смысл в структуре движения.","Перед входом оцени, как цена подошла к уровню и что делает после реакции."],"sourceTitle":"Горизонтальные уровни","sourceDuration":"43 минуты 36 секунд","lessonFormat":"video","sourceOrder":3,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='technical-horizontal-levels';
update public.learning_lessons set content=$${"videoUrl":"","article":"Поддержка и сопротивление лучше воспринимать как зоны, а не как математически точные линии. Цена может проколоть край зоны и всё равно сохранить её смысл. Само касание уровня не является достаточной причиной для входа.","examples":"Короткий материал о поддержке и сопротивлении: уровни нужно воспринимать как зоны и не входить только потому, что цена коснулась зоны.","practice":"Возьми 5 участков графика и вместо линий отметь зоны. Для каждой зоны запиши границы, реакцию цены внутри неё и место, где твой первоначальный сценарий перестаёт быть актуальным.","quiz":[{"id":"q1","type":"single_select","question":"Цена вошла внутрь области, которую ты отметил как уровень, но пока не показала реакции. Как действовать?","options":[{"value":"A","label":"Ждать подтверждения внутри/у зоны","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Считать касание автоматическим сигналом","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Сразу отменить любой сценарий","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Перенести зону после каждой свечи","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Отдели саму область от события, которое подтверждает сценарий."},{"id":"q2","type":"multi_select","question":"При проверке зоны перед решением какие записи полезнее сделать?","options":[{"value":"A","label":"Границы области","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Поведение цены внутри/у области","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Условие отмены сценария","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Только название уровня","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Фиксируй то, что помогает принять и отменить решение."},{"id":"q3","type":"true_false","question":"Для урока «Уровни — это зоны, а не линии» всегда достаточно одного признака, чтобы принять решение без проверки остальных условий.","options":[{"value":"true","label":"Верно","feedback":"Утверждение слишком сильно обобщает идею урока и игнорирует остальные условия."},{"value":"false","label":"Неверно","feedback":"Утверждение соответствует логике урока."}],"correctValues":["false"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Зона имеет ширину и допускает шум цены.","facts":["Зона имеет ширину и допускает шум цены.","Касание зоны ≠ готовый сигнал.","Нужен контекст и подтверждение реакции цены."],"sourceTitle":"Уровни — это зоны, а не линии","sourceDuration":"1 минута 31 секунда","lessonFormat":"video","sourceOrder":4,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='technical-levels-zones';
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Order Block» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Отдельный инструмент технического анализа: Order Block.","practice":"Найди 3 участка, где ты считаешь, что присутствует Order Block. Для каждого объясни, какое движение до и после него заставляет тебя выделить эту область и какое подтверждение ты ждёшь перед решением.","quiz":[{"id":"q1","type":"single_select","question":"На графике есть область, после которой началось заметное движение. Что нужно сделать перед использованием её как Order Block?","options":[{"value":"A","label":"Назвать её Order Block без проверки","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Изучить контекст движения до и после области","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"C","label":"Сразу открыть сделку в любую сторону","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Удалить все другие зоны","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Проверь, почему именно эта область важна для движения."},{"id":"q2","type":"multi_select","question":"Какие действия превращают материал урока в практический навык?","options":[{"value":"A","label":"Применить идею на истории","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Записать критерии решения","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Проверить спорные случаи","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Считать любой похожий график сигналом","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Ищи проверяемое применение, а не автоматическое распознавание."},{"id":"q3","type":"true_false","question":"Само наличие области после движения ещё не делает её готовым торговым сигналом.","options":[{"value":"true","label":"Верно","feedback":"Утверждение соответствует логике урока."},{"value":"false","label":"Неверно","feedback":"Такой вывод противоречит практической логике урока."}],"correctValues":["true"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Основная тема материала — Order Block.","facts":["Основная тема материала — Order Block.","Главное правило должно быть сформулировано своими словами.","Практика нужна для проверки понимания на графике, а не для механического повторения результата."],"sourceTitle":"Order Block","sourceDuration":"10 минут 28 секунд","lessonFormat":"video","sourceOrder":5,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='tools-order-block';
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Order Flow» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Отдельный материал по Order Flow и чтению потока сделок.","practice":"На трёх исторических участках попробуй описать Order Flow словами: кто проявляет инициативу, где давление меняется и что происходит с ценой после этого. Не используй название индикатора как объяснение — опиши наблюдаемое поведение.","quiz":[{"id":"q1","type":"single_select","question":"Цена продолжает расти, но по наблюдаемому поведению давление покупателей заметно ослабевает. Какой вопрос полезнее задать?","options":[{"value":"A","label":"Можно ли увеличить ставку?","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Изменилось ли преимущество сторон и что это делает с текущим сценарием?","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"C","label":"Какой индикатор даст самый красивый сигнал?","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Можно ли игнорировать цену?","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Сопоставь изменение давления с поведением самой цены."},{"id":"q2","type":"multi_select","question":"Какие действия превращают материал урока в практический навык?","options":[{"value":"A","label":"Применить идею на истории","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Записать критерии решения","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Проверить спорные случаи","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Считать любой похожий график сигналом","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Ищи проверяемое применение, а не автоматическое распознавание."},{"id":"q3","type":"true_false","question":"Для урока «Order Flow» всегда достаточно одного признака, чтобы принять решение без проверки остальных условий.","options":[{"value":"true","label":"Верно","feedback":"Утверждение слишком сильно обобщает идею урока и игнорирует остальные условия."},{"value":"false","label":"Неверно","feedback":"Утверждение соответствует логике урока."}],"correctValues":["false"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Основная тема материала — Order Flow.","facts":["Основная тема материала — Order Flow.","Главное правило должно быть сформулировано своими словами.","Практика нужна для проверки понимания на графике, а не для механического повторения результата."],"sourceTitle":"Order Flow","sourceDuration":"9 минут 49 секунд","lessonFormat":"video","sourceOrder":6,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='tools-order-flow';
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Fair Value Gap» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Материал по Fair Value Gap как отдельному инструменту чтения движения цены.","practice":"Найди 5 возможных Fair Value Gap. Для каждого отметь контекст появления, направление импульса и что произошло с ценой после формирования области. Два спорных примера специально пометь как спорные.","quiz":[{"id":"q1","type":"single_select","question":"Ты отметил возможный FVG, но не проверил, как он появился. Что следует сделать?","options":[{"value":"A","label":"Проверить импульс и контекст формирования области","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Считать любую пустоту на графике FVG","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Входить сразу после появления","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Удалить область, если она не дала прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Сначала установи происхождение области, затем оцени её роль."},{"id":"q2","type":"multi_select","question":"Какие действия превращают материал урока в практический навык?","options":[{"value":"A","label":"Применить идею на истории","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Записать критерии решения","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Проверить спорные случаи","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Считать любой похожий график сигналом","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Ищи проверяемое применение, а не автоматическое распознавание."},{"id":"q3","type":"true_false","question":"Для урока «Fair Value Gap» всегда достаточно одного признака, чтобы принять решение без проверки остальных условий.","options":[{"value":"true","label":"Верно","feedback":"Утверждение слишком сильно обобщает идею урока и игнорирует остальные условия."},{"value":"false","label":"Неверно","feedback":"Утверждение соответствует логике урока."}],"correctValues":["false"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Основная тема материала — Fair Value Gap.","facts":["Основная тема материала — Fair Value Gap.","Главное правило должно быть сформулировано своими словами.","Практика нужна для проверки понимания на графике, а не для механического повторения результата."],"sourceTitle":"Fair Value Gap","sourceDuration":"13 минут 18 секунд","lessonFormat":"video","sourceOrder":7,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='tools-fair-value-gap';
update public.learning_lessons set content=$${"videoUrl":"","article":"Индикатор — это инструмент чтения уже сформированного движения, а не самостоятельная кнопка BUY/SELL. В уроке собраны MACD, Stochastic, Awesome Oscillator, RSI и Momentum; смысл изучения — понимать, какую информацию даёт каждый инструмент и не перегружать решение.","examples":"Четвёртый эфир: MACD, Stochastic, Awesome Oscillator, RSI и Momentum.","practice":"Для каждого из MACD, Stochastic, Awesome Oscillator, RSI и Momentum найди по одному историческому примеру. Запиши, какую информацию ты получал от индикатора и какое решение принял бы только после проверки контекста.","quiz":[{"id":"q1","type":"single_select","question":"У двух индикаторов одновременно появились сигналы, но цена находится в неоднозначном участке графика. Что делать?","options":[{"value":"A","label":"Считать совпадение гарантией входа","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Проверить контекст рынка перед решением","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"C","label":"Удвоить размер позиции","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Выбрать индикатор с более сильным названием","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Индикаторы добавляют информацию, но не отменяют анализ ситуации."},{"id":"q2","type":"multi_select","question":"При разборе сигнала индикатора какие вопросы полезно задать?","options":[{"value":"A","label":"Что происходит с ценой","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Соответствует ли сигнал текущему контексту","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Закрыто ли требуемое условие","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Какой был прошлый плюс","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Оцени сигнал вместе с ценой и условиями его формирования."},{"id":"q3","type":"true_false","question":"Сигнал индикатора имеет смысл оценивать вместе с поведением цены и условиями, в которых он появился.","options":[{"value":"true","label":"Верно","feedback":"Утверждение соответствует логике урока."},{"value":"false","label":"Неверно","feedback":"Такой вывод противоречит практической логике урока."}],"correctValues":["true"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Не смешивай несколько индикаторов без понятной роли каждого.","facts":["Не смешивай несколько индикаторов без понятной роли каждого.","Сигнал индикатора нужно сопоставлять с графиком и контекстом.","Настройки и таймфрейм меняют характер сигнала."],"sourceTitle":"Индикаторы для уверенной торговли","sourceDuration":"49 минут 37 секунд","lessonFormat":"video","sourceOrder":8,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='indicators-fourth-live';
update public.learning_lessons set content=$${"videoUrl":"","article":"DeMarker используется для оценки состояния движения через положение относительно зон 80/20. В исходном материале указаны период 10, таймфрейм 15 секунд и экспирация M3, а также наблюдение за пересечением уровней на нескольких свечах.","examples":"DeMarker: период 10, уровни 80/20, гистограмма, таймфрейм 15 секунд и экспирация M3; в описании указано ждать пересечение 3–5 свечей.","practice":"Настрой DeMarker по параметрам урока и проведи 10 наблюдений на M15-ситуациях. Для каждого отметь состояние индикатора, направление рынка и был ли сигнал достаточно устойчивым для решения.","quiz":[{"id":"q1","type":"single_select","question":"DeMarker показывает состояние, которое обычно привлекает внимание трейдера, но рынок остаётся направленным. Как поступить?","options":[{"value":"A","label":"Проверить сигнал вместе с направлением рынка","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Игнорировать график и входить","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Сменить период после появления сигнала","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Считать любой уровень индикатора разворотом","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Сопоставь показание индикатора с поведением рынка."},{"id":"q2","type":"multi_select","question":"При разборе сигнала индикатора какие вопросы полезно задать?","options":[{"value":"A","label":"Что происходит с ценой","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Соответствует ли сигнал текущему контексту","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Закрыто ли требуемое условие","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Какой был прошлый плюс","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Оцени сигнал вместе с ценой и условиями его формирования."},{"id":"q3","type":"true_false","question":"Сигнал индикатора имеет смысл оценивать вместе с поведением цены и условиями, в которых он появился.","options":[{"value":"true","label":"Верно","feedback":"Утверждение соответствует логике урока."},{"value":"false","label":"Неверно","feedback":"Такой вывод противоречит практической логике урока."}],"correctValues":["true"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Период: 10; ориентиры: 80/20.","facts":["Период: 10; ориентиры: 80/20.","Не реагируй на единичное касание — смотри на развитие сигнала.","Контекст тренда и волатильности остаётся важен даже при наличии индикатора."],"sourceTitle":"DeMarker","sourceDuration":"5 минут 7 секунд","lessonFormat":"video","sourceOrder":9,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='indicators-demarker';
update public.learning_lessons set content=$${"videoUrl":"","article":"В уроке Moving Average рассматривается через периоды 2 и 5, таймфрейм 30 секунд и экспирацию M2. Ключевая идея — наблюдать пересечение средних как изменение краткосрочного баланса, а не считать само пересечение гарантией сделки.","examples":"Moving Average: периоды 2 и 5, таймфрейм 30 секунд, экспирация M2 и логика пересечения.","practice":"Настрой две Moving Average с периодами из урока. Найди 5 пересечений и раздели их на ситуации, где движение продолжилось, и ситуации, где пересечение оказалось слабым. Объясни различие контекстом.","quiz":[{"id":"q1","type":"single_select","question":"Две Moving Average пересеклись, но сразу после этого цена вернулась назад. Какой вывод наиболее полезен для обучения?","options":[{"value":"A","label":"Любое пересечение — готовая сделка","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Нужно оценивать качество пересечения в контексте движения","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"C","label":"Пересечение никогда не работает","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Следует менять периоды после каждого минуса","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Сравни сигнал с тем, что происходило до и после пересечения."},{"id":"q2","type":"multi_select","question":"При разборе сигнала индикатора какие вопросы полезно задать?","options":[{"value":"A","label":"Что происходит с ценой","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Соответствует ли сигнал текущему контексту","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Закрыто ли требуемое условие","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Какой был прошлый плюс","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Оцени сигнал вместе с ценой и условиями его формирования."},{"id":"q3","type":"true_false","question":"Для урока «Moving Average» всегда достаточно одного признака, чтобы принять решение без проверки остальных условий.","options":[{"value":"true","label":"Верно","feedback":"Утверждение слишком сильно обобщает идею урока и игнорирует остальные условия."},{"value":"false","label":"Неверно","feedback":"Утверждение соответствует логике урока."}],"correctValues":["false"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Периоды 2 и 5 задают очень быстрые средние.","facts":["Периоды 2 и 5 задают очень быстрые средние.","Пересечение показывает изменение краткосрочной динамики.","Закрытие свечи важно: не принимай решение по незавершённой свече."],"sourceTitle":"Moving Average","sourceDuration":"3 минуты 2 секунды","lessonFormat":"video","sourceOrder":10,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='indicators-moving-average';
update public.learning_lessons set content=$${"videoUrl":"","article":"Stochastic в исходном материале задан уровнями 20/80 и параметрами K14, D3, slowing3. Урок отдельно подчёркивает работу после закрытия свечи и учёт тренда.","examples":"Stochastic: уровни 20/80, K14, D3, slowing 3, M5/M1, работа после закрытия свечи и учёт тренда.","practice":"Настрой Stochastic по параметрам урока. Найди 6 сигналов в разных условиях и для каждого дождись закрытия свечи. Отдельно отметь, как направление тренда изменило бы твоё решение.","quiz":[{"id":"q1","type":"single_select","question":"Stochastic дал сигнал внутри сильного движения. Что нужно проверить прежде всего?","options":[{"value":"A","label":"Закрытие свечи и направление рынка","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Только размер потенциальной прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Количество открытых сделок","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Цвет интерфейса графика","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Не оценивай сигнал до завершения условия, указанного в материале."},{"id":"q2","type":"multi_select","question":"При разборе сигнала индикатора какие вопросы полезно задать?","options":[{"value":"A","label":"Что происходит с ценой","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Соответствует ли сигнал текущему контексту","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Закрыто ли требуемое условие","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Какой был прошлый плюс","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Оцени сигнал вместе с ценой и условиями его формирования."},{"id":"q3","type":"true_false","question":"Сигнал индикатора имеет смысл оценивать вместе с поведением цены и условиями, в которых он появился.","options":[{"value":"true","label":"Верно","feedback":"Утверждение соответствует логике урока."},{"value":"false","label":"Неверно","feedback":"Такой вывод противоречит практической логике урока."}],"correctValues":["true"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"20/80 — зоны, а не автоматические точки входа.","facts":["20/80 — зоны, а не автоматические точки входа.","Параметры K14/D3/slowing3 должны оставаться фиксированными при отработке учебного сценария.","Сигнал оценивается вместе с трендом и закрытием свечи."],"sourceTitle":"Stochastic","sourceDuration":"7 минут 28 секунд","lessonFormat":"video","sourceOrder":11,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='indicators-stochastic';
update public.learning_lessons set content=$${"videoUrl":"","article":"Пробой — это не просто выход цены за линию. В уроке акцент сделан на поиске пробоя, отличии настоящего движения от фейк-пробоя и выборе точки входа. Поэтому сначала определяется уровень и контекст, затем оценивается реакция после выхода.","examples":"Как торговать пробои, находить их, избегать главных ошибок, видеть фейк-пробои и выбирать точки входа.","practice":"Найди 5 пробоев: два качественных, два ложных и один спорный. Для каждого до просмотра результата сформулируй сценарий, точку входа и условие отмены. Только после этого проверь, что произошло.","quiz":[{"id":"q1","type":"single_select","question":"Цена вышла за границу диапазона, но почти сразу вернулась внутрь. Как классифицировать ситуацию для дальнейшего анализа?","options":[{"value":"A","label":"Как возможный ложный пробой, требующий проверки реакции","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Как гарантированное продолжение","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Как сигнал увеличить риск","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Как причину закрыть весь терминал","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Сравни поведение после выхода с самим фактом выхода."},{"id":"q2","type":"multi_select","question":"Что стоит зафиксировать до проверки результата стратегического входа?","options":[{"value":"A","label":"Условия входа","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Условие отмены","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Контекст движения","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Фактическую будущую прибыль","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Сначала зафиксируй решение, затем смотри результат."},{"id":"q3","type":"true_false","question":"Факт выхода цены за границу диапазона ещё не доказывает, что пробой продолжится.","options":[{"value":"true","label":"Верно","feedback":"Утверждение соответствует логике урока."},{"value":"false","label":"Неверно","feedback":"Такой вывод противоречит практической логике урока."}],"correctValues":["true"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Пробой нужно отличать от ложного выхода за уровень.","facts":["Пробой нужно отличать от ложного выхода за уровень.","Контекст и качество движения важнее самого факта пересечения.","Точка входа должна иметь объяснимую причину, а не строиться на погоне за движением."],"sourceTitle":"Стратегия торговли по пробоям","sourceDuration":"14 минут 3 секунды","lessonFormat":"video","sourceOrder":12,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='strategies-breakouts';
update public.learning_lessons set content=$${"videoUrl":"","article":"Связка SuperTrend + Moving Average нужна для согласования направления движения. SuperTrend даёт контекст направления, а средняя помогает видеть краткосрочную динамику. Примеры в источнике показывают применение на коротком таймфрейме.","examples":"Связка SuperTrend + Moving Average на коротком таймфрейме; в примерах указаны AUD/CAD и EUR/GBP, 1 минута и сделки по +$89.","practice":"На истории найди 5 пересечений/совпадений SuperTrend и Moving Average. Для каждого запиши направление, контекст и решение: входить, ждать или пропустить. Обязательно объясни выбор.","quiz":[{"id":"q1","type":"single_select","question":"SuperTrend и Moving Average дают согласованный сигнал, но структура рынка перед ним слабая. Что выбрать?","options":[{"value":"A","label":"Рассмотреть сценарий, но проверить контекст","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Входить независимо от контекста","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Игнорировать цену полностью","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Сразу удваивать позицию","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Согласованность инструментов — не единственный критерий."},{"id":"q2","type":"multi_select","question":"Что стоит зафиксировать до проверки результата стратегического входа?","options":[{"value":"A","label":"Условия входа","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Условие отмены","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Контекст движения","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Фактическую будущую прибыль","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Сначала зафиксируй решение, затем смотри результат."},{"id":"q3","type":"true_false","question":"Для урока «SuperTrend + Moving Average» всегда достаточно одного признака, чтобы принять решение без проверки остальных условий.","options":[{"value":"true","label":"Верно","feedback":"Утверждение слишком сильно обобщает идею урока и игнорирует остальные условия."},{"value":"false","label":"Неверно","feedback":"Утверждение соответствует логике урока."}],"correctValues":["false"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Оба инструмента должны выполнять разные роли, а не дублировать друг друга.","facts":["Оба инструмента должны выполнять разные роли, а не дублировать друг друга.","Сначала определяй направление, затем ищи точку входа.","Примеры сделок не превращают сигнал в гарантию результата."],"sourceTitle":"SuperTrend + Moving Average","sourceDuration":"Пост","lessonFormat":"post","sourceOrder":13,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='strategies-supertrend-ma';
update public.learning_lessons set content=$${"videoUrl":"","article":"Donchian Channel с периодом 22 показывает диапазон экстремумов выбранного числа свечей. В исходном сценарии используется M1 и экспирация 1–2 минуты. Смысл инструмента — видеть границы текущего диапазона и оценивать выход из него.","examples":"Donchian Channel: период 22, M1, экспирация 1–2 минуты.","practice":"Настрой Donchian Channel с периодом 22. Найди 5 выходов цены за границы и проверь, что произошло в следующие 1–2 минуты. Раздели случаи по качеству и объясни причины.","quiz":[{"id":"q1","type":"single_select","question":"Цена коснулась верхней границы Donchian Channel и сразу вернулась. Что проверять дальше?","options":[{"value":"A","label":"Как развивалось движение после касания/выхода","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Только размер канала на другом рынке","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Случайный индикатор","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Сумму прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Интересен не сам факт касания, а дальнейшее поведение цены."},{"id":"q2","type":"multi_select","question":"Что стоит зафиксировать до проверки результата стратегического входа?","options":[{"value":"A","label":"Условия входа","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Условие отмены","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Контекст движения","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Фактическую будущую прибыль","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Сначала зафиксируй решение, затем смотри результат."},{"id":"q3","type":"true_false","question":"Касание границы Donchian Channel и дальнейшее развитие движения — не одно и то же событие.","options":[{"value":"true","label":"Верно","feedback":"Утверждение соответствует логике урока."},{"value":"false","label":"Неверно","feedback":"Такой вывод противоречит практической логике урока."}],"correctValues":["true"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Период 22 задаёт окно наблюдения.","facts":["Период 22 задаёт окно наблюдения.","Граница канала отражает недавний максимум/минимум, а не будущее направление.","Выход за границу нужно оценивать вместе с контекстом."],"sourceTitle":"Donchian Channel","sourceDuration":"4 минуты 17 секунд","lessonFormat":"video","sourceOrder":14,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='strategies-donchian';
update public.learning_lessons set content=$${"videoUrl":"","article":"Стратегия Александра объединяет Bollinger Bands, RSI и Moving Average. В источнике указаны Bollinger period 20, deviation 2 и EMA, а рабочий контекст — M2–M3. Сила схемы в совместном чтении цены, волатильности и импульса.","examples":"Bollinger Bands + RSI + Moving Average; Bollinger period 20, deviation 2, EMA, M2–M3.","practice":"Собери 5 исторических ситуаций по связке Bollinger Bands + RSI + Moving Average. Не ищи совпадение всех трёх индикаторов механически: опиши, что каждый из них добавляет к решению и где сценарий лучше пропустить.","quiz":[{"id":"q1","type":"single_select","question":"Bollinger Bands, RSI и Moving Average дают неодинаковую картину. Как поступить?","options":[{"value":"C","label":"Считать конфликт сигналов причиной входа","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Увеличить риск","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"A","label":"Разобрать роль каждого инструмента и общий контекст","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Выбрать любой один сигнал","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Разложи связку на отдельные элементы и затем собери общий сценарий."},{"id":"q2","type":"multi_select","question":"Что стоит зафиксировать до проверки результата стратегического входа?","options":[{"value":"A","label":"Условия входа","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Условие отмены","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Контекст движения","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Фактическую будущую прибыль","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Сначала зафиксируй решение, затем смотри результат."},{"id":"q3","type":"true_false","question":"Если Bollinger Bands, RSI и Moving Average показывают разную картину, конфликт нужно разобрать, а не скрыть.","options":[{"value":"true","label":"Верно","feedback":"Утверждение соответствует логике урока."},{"value":"false","label":"Неверно","feedback":"Такой вывод противоречит практической логике урока."}],"correctValues":["true"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Bollinger показывает положение цены внутри динамического диапазона.","facts":["Bollinger показывает положение цены внутри динамического диапазона.","RSI добавляет информацию о силе движения.","Moving Average помогает не потерять направление контекста."],"sourceTitle":"Стратегия Александра","sourceDuration":"4 минуты 9 секунд","lessonFormat":"video","sourceOrder":15,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='strategies-alexander';
update public.learning_lessons set content=$${"videoUrl":"","article":"Связка Schaff Trend Cycle + Donchian Channel сочетает оценку трендового импульса с границами диапазона. Один инструмент отвечает за состояние движения, другой — за положение цены относительно экстремумов.","examples":"Связка Schaff Trend Cycle и Donchian Channel для торгового сценария.","practice":"Найди 5 ситуаций, где Schaff Trend Cycle и Donchian Channel дают возможность сформировать единый сценарий. Для каждой запиши, что показывает каждый инструмент и что должно произойти для входа.","quiz":[{"id":"q1","type":"single_select","question":"Schaff Trend Cycle показывает одно направление, а Donchian пока не подтверждает движение. Что разумнее?","options":[{"value":"C","label":"Игнорировать канал","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Менять актив каждые 10 секунд","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"A","label":"Ждать согласования сценария/подтверждения","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Входить только из-за одного показания","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Проверь, что оба элемента дают для одного сценария."},{"id":"q2","type":"multi_select","question":"Что стоит зафиксировать до проверки результата стратегического входа?","options":[{"value":"A","label":"Условия входа","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Условие отмены","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Контекст движения","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Фактическую будущую прибыль","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Сначала зафиксируй решение, затем смотри результат."},{"id":"q3","type":"true_false","question":"Один компонент связки Schaff Trend Cycle + Donchian Channel не обязан автоматически подтверждать весь сценарий.","options":[{"value":"true","label":"Верно","feedback":"Утверждение соответствует логике урока."},{"value":"false","label":"Неверно","feedback":"Такой вывод противоречит практической логике урока."}],"correctValues":["true"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Не рассматривай два индикатора как два независимых сигнала BUY/SELL.","facts":["Не рассматривай два индикатора как два независимых сигнала BUY/SELL.","Ищи согласование направления и положения цены.","Если контекст противоречивый, решение должно быть пропущено, а не выдумано."],"sourceTitle":"Schaff Trend Cycle + Donchian Channel","sourceDuration":"6 минут 33 секунды","lessonFormat":"video","sourceOrder":16,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='strategies-schaff-donchian';
update public.learning_lessons set content=$${"videoUrl":"","article":"Moving Average помогает читать направление/динамику, а Fractals — локальные экстремумы. Их совместное использование полезно, когда экстремум оценивается относительно текущего направления, а не сам по себе.","examples":"Торговый сценарий с Moving Average и Fractals.","practice":"Найди 5 примеров взаимодействия Moving Average и Fractals. Для каждого опиши направление, локальный экстремум и момент, когда решение становится достаточно определённым.","quiz":[{"id":"q1","type":"single_select","question":"Появился Fractal, но направление по Moving Average не поддерживает твою идею. Что выбрать?","options":[{"value":"A","label":"Не считать один Fractal достаточным основанием","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Игнорировать Moving Average всегда","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Входить из-за формы свечи","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Увеличить риск","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Сравни локальную структуру с направлением более общего движения."},{"id":"q2","type":"multi_select","question":"Что стоит зафиксировать до проверки результата стратегического входа?","options":[{"value":"A","label":"Условия входа","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Условие отмены","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Контекст движения","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Фактическую будущую прибыль","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Сначала зафиксируй решение, затем смотри результат."},{"id":"q3","type":"true_false","question":"Для урока «Moving Average + Fractals» всегда достаточно одного признака, чтобы принять решение без проверки остальных условий.","options":[{"value":"true","label":"Верно","feedback":"Утверждение слишком сильно обобщает идею урока и игнорирует остальные условия."},{"value":"false","label":"Неверно","feedback":"Утверждение соответствует логике урока."}],"correctValues":["false"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Фрактал — это локальная структура, а не самостоятельная причина входа.","facts":["Фрактал — это локальная структура, а не самостоятельная причина входа.","MA задаёт контекст направления.","Сначала оцени структуру, затем ищи точку решения."],"sourceTitle":"Moving Average + Fractals","sourceDuration":"5 минут 21 секунда","lessonFormat":"video","sourceOrder":17,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='strategies-ma-fractals';
update public.learning_lessons set content=$${"videoUrl":"","article":"Сценарий Giant Candle из источника относится к OTC: таймфрейм 5 секунд, большая свеча сравнивается с 3–5 предыдущими, после чего рассматривается противоположный вход с экспирацией 3 секунды. Это специальный сценарий, который нельзя переносить на любой график без проверки условий.","examples":"OTC, таймфрейм 5 секунд, большая свеча против 3–5 предыдущих, вход в противоположную сторону, экспирация 3 секунды; только после новой ситуации.","practice":"Найди 5 примеров Giant Candle и сначала опиши ситуацию без просмотра следующих свечей. Отметь, соответствует ли движение условиям урока и что должно произойти, чтобы сценарий был отменён.","quiz":[{"id":"q1","type":"single_select","question":"На OTC появляется необычно большая свеча после нескольких небольших. Что сделать перед противоположным входом?","options":[{"value":"C","label":"Использовать максимальную экспирацию","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Игнорировать предыдущие свечи","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"A","label":"Проверить, что ситуация действительно соответствует условиям Giant Candle","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Входить на любой большой свече","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Сначала проверь саму формацию и последовательность свечей."},{"id":"q2","type":"multi_select","question":"Что стоит зафиксировать до проверки результата стратегического входа?","options":[{"value":"A","label":"Условия входа","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Условие отмены","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Контекст движения","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Фактическую будущую прибыль","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Сначала зафиксируй решение, затем смотри результат."},{"id":"q3","type":"true_false","question":"Для урока «Giant Candle» всегда достаточно одного признака, чтобы принять решение без проверки остальных условий.","options":[{"value":"true","label":"Верно","feedback":"Утверждение слишком сильно обобщает идею урока и игнорирует остальные условия."},{"value":"false","label":"Неверно","feedback":"Утверждение соответствует логике урока."}],"correctValues":["false"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Сначала должна быть действительно аномально большая свеча относительно 3–5 предыдущих.","facts":["Сначала должна быть действительно аномально большая свеча относительно 3–5 предыдущих.","Сценарий предусматривает противоположное направление, но только при выполнении условий.","После новой ситуации нельзя механически повторять старый сигнал."],"sourceTitle":"Giant Candle","sourceDuration":"Пост","lessonFormat":"post","sourceOrder":18,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='strategies-giant-candle';
update public.learning_lessons set content=$${"videoUrl":"","article":"Паттерн 2-of-3 строится на последовательности зелёная–красная–зелёная. В источнике указано: обычные валютные пары, 30 секунд, третья зелёная должна закрыться на уровне/выше максимума первой зелёной, экспирация 2 минуты.","examples":"Обычные валютные пары, 30 секунд, последовательность зелёная–красная–зелёная; третья зелёная закрывается на/выше максимума первой; экспирация 2 минуты.","practice":"Найди 5 формаций green-red-green. Для каждой проверь условие по третьей свече только после её полного закрытия. Запиши, соответствует ли структура критериям урока и почему.","quiz":[{"id":"q1","type":"single_select","question":"Формация green-red-green появилась, но третья свеча ещё не закрылась. Что делать?","options":[{"value":"C","label":"Входить по первой свече","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Менять таймфрейм после каждой секунды","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"A","label":"Дождаться полного закрытия и только затем проверять критерий","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Считать формацию завершённой заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ключевое условие связано с завершением третьей свечи."},{"id":"q2","type":"multi_select","question":"Что стоит зафиксировать до проверки результата стратегического входа?","options":[{"value":"A","label":"Условия входа","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Условие отмены","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Контекст движения","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Фактическую будущую прибыль","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Сначала зафиксируй решение, затем смотри результат."},{"id":"q3","type":"true_false","question":"Для урока «2-of-3» всегда достаточно одного признака, чтобы принять решение без проверки остальных условий.","options":[{"value":"true","label":"Верно","feedback":"Утверждение слишком сильно обобщает идею урока и игнорирует остальные условия."},{"value":"false","label":"Неверно","feedback":"Утверждение соответствует логике урока."}],"correctValues":["false"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Последовательность свечей должна быть полной: зелёная → красная → зелёная.","facts":["Последовательность свечей должна быть полной: зелёная → красная → зелёная.","Ключевое условие — закрытие третьей свечи на/выше максимума первой зелёной.","Решение принимается после полного закрытия свечи."],"sourceTitle":"2-of-3","sourceDuration":"Пост","lessonFormat":"post","sourceOrder":19,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='strategies-two-of-three';
update public.learning_lessons set content=$${"videoUrl":"","article":"База психологии в источнике посвящена типичным проблемам новичков и пошаговым действиям, которые помогают не повторять их. Главная задача — замечать собственные реакции до того, как они превращаются в плохое решение.","examples":"Шестой эфир: проблемы новичков, пошаговые инструкции и базовая психология трейдинга.","practice":"Составь журнал из 10 решений: что ты хотел сделать, что чувствовал и что сделал фактически. Для трёх эмоциональных решений укажи, какое правило из урока могло остановить действие.","quiz":[{"id":"q1","type":"single_select","question":"После серии минусов трейдер хочет увеличить риск только ради возврата к прежнему балансу. Какую проблему стоит распознать?","options":[{"value":"C","label":"Подтверждение сильного сигнала","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Нормальную обязательную часть любой сделки","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"A","label":"Попытку отыграться через эмоциональное изменение риска","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Хорошую адаптацию стратегии","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Отдели заранее заданный риск от реакции на результат предыдущих сделок."},{"id":"q2","type":"multi_select","question":"Что помогает отделить системное решение от эмоционального?","options":[{"value":"A","label":"Заранее заданный риск","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Записанное условие входа","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Правило после серии минусов","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Изменение размера сделки по настроению","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Ищи заранее определённые правила, а не реакцию на эмоцию."},{"id":"q3","type":"true_false","question":"Для урока «Психология трейдинга — база» всегда достаточно одного признака, чтобы принять решение без проверки остальных условий.","options":[{"value":"true","label":"Верно","feedback":"Утверждение слишком сильно обобщает идею урока и игнорирует остальные условия."},{"value":"false","label":"Неверно","feedback":"Утверждение соответствует логике урока."}],"correctValues":["false"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Проблему нужно сначала назвать, затем определить триггер и действие контроля.","facts":["Проблему нужно сначала назвать, затем определить триггер и действие контроля.","Результат одной сделки не должен полностью менять план.","Психология работает вместе с системой, а не вместо неё."],"sourceTitle":"Психология трейдинга — база","sourceDuration":"59 минут 45 секунд","lessonFormat":"video","sourceOrder":20,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='psychology-sixth-live';
update public.learning_lessons set content=$${"videoUrl":"https://youtu.be/a9y1pxJfDRU","article":"Главный принцип психологии нужно переводить из общей фразы в конкретное торговое поведение. Если принцип нельзя проверить по действиям трейдера, он остаётся абстракцией.","examples":"Отдельный урок по психологии трейдинга. Домашнее задание озвучено в самом видео.","practice":"После просмотра сформулируй главный психологический принцип урока своими словами и проверь его на трёх собственных торговых решениях. Для каждого отметь, где эмоция могла изменить исходный план.","quiz":[{"id":"q1","type":"single_select","question":"После серии минусов трейдер хочет увеличить риск только ради возврата к прежнему балансу. Какую проблему стоит распознать?","options":[{"value":"A","label":"Попытку отыграться через эмоциональное изменение риска","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Хорошую адаптацию стратегии","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Подтверждение сильного сигнала","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Нормальную обязательную часть любой сделки","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Отдели заранее заданный риск от реакции на результат предыдущих сделок."},{"id":"q2","type":"multi_select","question":"Что помогает отделить системное решение от эмоционального?","options":[{"value":"A","label":"Заранее заданный риск","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Записанное условие входа","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Правило после серии минусов","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Изменение размера сделки по настроению","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Ищи заранее определённые правила, а не реакцию на эмоцию."},{"id":"q3","type":"true_false","question":"Психологическое правило имеет практический смысл, когда его можно проверить на собственных решениях, а не только повторить словами.","options":[{"value":"true","label":"Верно","feedback":"Утверждение соответствует логике урока."},{"value":"false","label":"Неверно","feedback":"Такой вывод противоречит практической логике урока."}],"correctValues":["true"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Фиксируй состояние до сделки, а не только результат после неё.","facts":["Фиксируй состояние до сделки, а не только результат после неё.","Разделяй качество решения и финансовый исход.","Домашнее задание должно превращаться в наблюдаемое действие."],"sourceTitle":"Психология трейдинга | Урок 1: главный принцип","sourceDuration":"YouTube","lessonFormat":"video","sourceOrder":21,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='psychology-main-principle';
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Инвестинг от А до Я» связывает выбор валютных пар, фильтрацию сигналов и личный подход автора. Практическая цель — научиться не брать каждый доступный сигнал, а выбирать контекст, который соответствует плану.","examples":"Как выбрать валютные пары, какие сигналы пропускать, как автор торгует и выходит в плюс, и какие ошибки делают новички.","practice":"Выбери 5 валютных пар и составь для каждой короткий фильтр: когда рассматриваешь её, какие ситуации пропускаешь и что должно совпасть перед входом. Затем сравни пары и выбери только те, где критерии выполнимы.","quiz":[{"id":"q1","type":"single_select","question":"При выборе пары для работы ты видишь красивый сигнал, но он не проходит твой заранее заданный фильтр. Что делать?","options":[{"value":"A","label":"Пропустить его","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Изменить фильтр ради этого сигнала","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Увеличить риск","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Открыть сделку на другой паре без анализа","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Проверь, сохраняется ли решение после применения всех собственных критериев."},{"id":"q2","type":"multi_select","question":"Какие действия превращают материал урока в практический навык?","options":[{"value":"A","label":"Применить идею на истории","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Записать критерии решения","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Проверить спорные случаи","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Считать любой похожий график сигналом","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Ищи проверяемое применение, а не автоматическое распознавание."},{"id":"q3","type":"true_false","question":"Если сигнал не проходит заранее выбранный фильтр, его привлекательность сама по себе не является причиной менять фильтр.","options":[{"value":"true","label":"Верно","feedback":"Утверждение соответствует логике урока."},{"value":"false","label":"Неверно","feedback":"Такой вывод противоречит практической логике урока."}],"correctValues":["true"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Выбор инструмента — часть стратегии.","facts":["Выбор инструмента — часть стратегии.","Пропуск слабого сигнала является частью процесса, а не упущенной возможностью.","Личный подход нужно превращать в проверяемые правила."],"sourceTitle":"Инвестинг от А до Я — мой личный соус","sourceDuration":"19 минут 1 секунда","lessonFormat":"video","sourceOrder":22,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='practice-investing-a-to-z';
update public.learning_lessons set content=$${"videoUrl":"","article":"Время экспирации должно соответствовать характеру движения. Источник отдельно сравнивает импульс и флет и подчёркивает, что 1 минута не является универсальным решением.","examples":"На что смотреть перед входом, как отличается экспирация при импульсе и флете и почему 1 минута не всегда решение.","practice":"Возьми 8 исторических входов с разным характером движения. Для каждого отдельно выбери срок экспирации и объясни его через тип движения, а не через желание быстрее получить результат.","quiz":[{"id":"q1","type":"single_select","question":"Вход выглядит одинаково, но в одном случае движение импульсное, а в другом рынок находится во флэте. Что это меняет?","options":[{"value":"A","label":"Подход к выбору времени экспирации","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Ничего","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Только название валютной пары","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Только размер депозита","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Срок рассматривается через характер движения, а не как постоянная величина."},{"id":"q2","type":"multi_select","question":"Какие действия превращают материал урока в практический навык?","options":[{"value":"A","label":"Применить идею на истории","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Записать критерии решения","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Проверить спорные случаи","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Считать любой похожий график сигналом","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Ищи проверяемое применение, а не автоматическое распознавание."},{"id":"q3","type":"true_false","question":"Одинаковый вход при разном характере движения не обязательно требует одинакового подхода к экспирации.","options":[{"value":"true","label":"Верно","feedback":"Утверждение соответствует логике урока."},{"value":"false","label":"Неверно","feedback":"Такой вывод противоречит практической логике урока."}],"correctValues":["true"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Сначала оцени характер движения, потом выбирай экспирацию.","facts":["Сначала оцени характер движения, потом выбирай экспирацию.","Импульс и флет требуют разного ожидания по времени.","Точный вход не гарантирует результата при неподходящей экспирации."],"sourceTitle":"Как подбирать время экспирации для сделки?","sourceDuration":"7 минут 57 секунд","lessonFormat":"video","sourceOrder":23,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='timing-expiration';
update public.learning_lessons set content=$${"videoUrl":"","article":"Торговая интуиция в контексте урока — это не угадывание, а накопленное распознавание повторяющихся ситуаций. Важно отделять опытное ощущение от импульсивного желания войти.","examples":"Автор показывает сделки по интуиции и объясняет подход на примере трёх сделок.","practice":"Выбери 5 исторических ситуаций и сначала запиши интуитивное решение, не открывая следующие свечи. Затем отдельно разложи каждое решение на наблюдаемые признаки и проверь, можно ли объяснить интуицию правилами.","quiz":[{"id":"q1","type":"single_select","question":"Трейдер говорит: «Я просто почувствовал вход». Что полезнее сделать для обучения этой интуиции?","options":[{"value":"A","label":"Разложить решение на наблюдаемые признаки после фиксации ситуации","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Считать интуицию необъяснимой","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Увеличить размер позиции","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Перестать вести записи","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Попробуй превратить ощущение в набор наблюдений, которые можно повторно проверить."},{"id":"q2","type":"multi_select","question":"Какие действия превращают материал урока в практический навык?","options":[{"value":"A","label":"Применить идею на истории","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Записать критерии решения","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Проверить спорные случаи","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Считать любой похожий график сигналом","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Ищи проверяемое применение, а не автоматическое распознавание."},{"id":"q3","type":"true_false","question":"Для урока «Торговля по интуиции» всегда достаточно одного признака, чтобы принять решение без проверки остальных условий.","options":[{"value":"true","label":"Верно","feedback":"Утверждение слишком сильно обобщает идею урока и игнорирует остальные условия."},{"value":"false","label":"Неверно","feedback":"Утверждение соответствует логике урока."}],"correctValues":["false"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Интуиция должна опираться на наблюдаемые признаки рынка.","facts":["Интуиция должна опираться на наблюдаемые признаки рынка.","Проверяй интуитивный вход теми же правилами, что и обычный.","Три удачных сделки не доказывают устойчивость подхода."],"sourceTitle":"Торговля по интуиции","sourceDuration":"11 минут 53 секунды","lessonFormat":"video","sourceOrder":24,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='practice-intuition';
update public.learning_lessons set content=$${"videoUrl":"","article":"Разбор недели нужен не для поиска виноватой стратегии, а для выявления повторяющихся причин потерь. Сделку следует оценивать по процессу: контекст, вход, риск, дисциплина и результат.","examples":"Пятый эфир: причины потери средств, разбор сделок и причины различий в результатах трейдеров.","practice":"Возьми 10 своих сделок за неделю и классифицируй каждую ошибку: анализ, исполнение, риск или психология. Выбери повторяющуюся категорию и составь одно конкретное правило, которое предотвратит её повторение.","quiz":[{"id":"q1","type":"single_select","question":"За неделю пять минусов оказались следствием нарушения одного и того же правила. Какой следующий шаг наиболее полезен?","options":[{"value":"C","label":"Увеличить риск следующей сделки","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Считать неделю случайностью","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"A","label":"Сформулировать конкретную профилактику этой ошибки","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Удалить все минусовые сделки","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи повторяемую причину, которую можно изменить в процессе."},{"id":"q2","type":"multi_select","question":"Какие действия превращают материал урока в практический навык?","options":[{"value":"A","label":"Применить идею на истории","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Записать критерии решения","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Проверить спорные случаи","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Считать любой похожий график сигналом","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Ищи проверяемое применение, а не автоматическое распознавание."},{"id":"q3","type":"true_false","question":"Разбор недели теряет смысл, если смотреть только на итоговый P&L и не искать повторяющиеся причины решений.","options":[{"value":"true","label":"Верно","feedback":"Утверждение соответствует логике урока."},{"value":"false","label":"Неверно","feedback":"Такой вывод противоречит практической логике урока."}],"correctValues":["true"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Одна убыточная сделка не равна плохой системе.","facts":["Одна убыточная сделка не равна плохой системе.","Повторяющаяся ошибка важнее единичного результата.","Сравнивай причины разных результатов, а не только суммы P&L."],"sourceTitle":"Итоги недели — разбор ошибок","sourceDuration":"38 минут 57 секунд","lessonFormat":"video","sourceOrder":25,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='trade-review-week-errors';
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Разбор рынка — 15.07.2025» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: разбор рынка — 15.07.2025. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Пересмотри разбор и сделай самостоятельный replay: останови график до ключевого момента, запиши свой сценарий и только потом сравни с логикой разбора.","quiz":[{"id":"q1","type":"single_select","question":"Ты разбираешь ситуацию из урока «Разбор рынка — 15.07.2025». График пока не дал подтверждения твоей первоначальной идеи. Что разумнее?","options":[{"value":"C","label":"Увеличить риск ради уверенности","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Считать отсутствие подтверждения подтверждением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"A","label":"Сохранить сценарий как гипотезу и ждать подтверждения/отмены","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Войти только потому, что идея уже придумана","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Отделяй гипотезу от подтверждённого торгового решения."},{"id":"q2","type":"multi_select","question":"Что полезно записать при самостоятельном разборе рынка?","options":[{"value":"A","label":"Контекст","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Рабочий сценарий","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Условие отмены","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Только итог сделки","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Смысл упражнения — восстановить логику решения до результата."},{"id":"q3","type":"true_false","question":"Для урока «Разбор рынка — 15.07.2025» всегда достаточно одного признака, чтобы принять решение без проверки остальных условий.","options":[{"value":"true","label":"Верно","feedback":"Утверждение слишком сильно обобщает идею урока и игнорирует остальные условия."},{"value":"false","label":"Неверно","feedback":"Утверждение соответствует логике урока."}],"correctValues":["false"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Главная тема урока — Разбор рынка — 15.07.2025.","facts":["Главная тема урока — Разбор рынка — 15.07.2025.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Разбор рынка — 15.07.2025","sourceDuration":"7 минут 18 секунд","lessonFormat":"video","sourceOrder":26,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='market-15072025';
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Разбор рынка — понедельник 25 августа» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: разбор рынка — понедельник 25 августа. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Повтори разбор в режиме replay. На каждом ключевом участке сначала запиши направление и основание решения, затем сравни с тем, что показывается в уроке.","quiz":[{"id":"q1","type":"single_select","question":"Ты разбираешь ситуацию из урока «Разбор рынка — понедельник 25 августа». График пока не дал подтверждения твоей первоначальной идеи. Что разумнее?","options":[{"value":"A","label":"Сохранить сценарий как гипотезу и ждать подтверждения/отмены","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Войти только потому, что идея уже придумана","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Увеличить риск ради уверенности","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Считать отсутствие подтверждения подтверждением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Отделяй гипотезу от подтверждённого торгового решения."},{"id":"q2","type":"multi_select","question":"Что полезно записать при самостоятельном разборе рынка?","options":[{"value":"A","label":"Контекст","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Рабочий сценарий","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Условие отмены","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Только итог сделки","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Смысл упражнения — восстановить логику решения до результата."},{"id":"q3","type":"true_false","question":"Для урока «Разбор рынка — понедельник 25 августа» всегда достаточно одного признака, чтобы принять решение без проверки остальных условий.","options":[{"value":"true","label":"Верно","feedback":"Утверждение слишком сильно обобщает идею урока и игнорирует остальные условия."},{"value":"false","label":"Неверно","feedback":"Утверждение соответствует логике урока."}],"correctValues":["false"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Главная тема урока — Разбор рынка — понедельник 25 августа.","facts":["Главная тема урока — Разбор рынка — понедельник 25 августа.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Разбор рынка — понедельник 25 августа","sourceDuration":"10 минут 23 секунды","lessonFormat":"video","sourceOrder":27,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='market-25aug';
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Разбор рынка — 28.08.2025» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: разбор рынка — 28.08.2025. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Выбери три участка из разбора и для каждого выпиши контекст, реакцию цены и ожидаемый следующий сценарий до того, как увидишь продолжение.","quiz":[{"id":"q1","type":"single_select","question":"Ты разбираешь ситуацию из урока «Разбор рынка — 28.08.2025». График пока не дал подтверждения твоей первоначальной идеи. Что разумнее?","options":[{"value":"A","label":"Сохранить сценарий как гипотезу и ждать подтверждения/отмены","feedback":"Выбор согласуется с описанной ситуацией."},{"value":"B","label":"Войти только потому, что идея уже придумана","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Увеличить риск ради уверенности","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Считать отсутствие подтверждения подтверждением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Отделяй гипотезу от подтверждённого торгового решения."},{"id":"q2","type":"multi_select","question":"Что полезно записать при самостоятельном разборе рынка?","options":[{"value":"A","label":"Контекст","feedback":"Этот вариант подходит к условиям задачи."},{"value":"B","label":"Рабочий сценарий","feedback":"Этот вариант подходит к условиям задачи."},{"value":"C","label":"Условие отмены","feedback":"Этот вариант подходит к условиям задачи."},{"value":"D","label":"Только итог сделки","feedback":"Этот вариант не следует из условий задачи."}],"correctValues":["A","B","C"],"hint":"Смысл упражнения — восстановить логику решения до результата."},{"id":"q3","type":"true_false","question":"При самостоятельном разборе рынка полезно сначала сформировать собственный сценарий, а затем сравнить его с развитием цены.","options":[{"value":"true","label":"Верно","feedback":"Утверждение соответствует логике урока."},{"value":"false","label":"Неверно","feedback":"Такой вывод противоречит практической логике урока."}],"correctValues":["true"],"hint":"Проверь, достаточно ли одного признака или нужно учитывать несколько условий ситуации."}],"keyTakeaway":"Главная тема урока — Разбор рынка — 28.08.2025.","facts":["Главная тема урока — Разбор рынка — 28.08.2025.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Разбор рынка — 28.08.2025","sourceDuration":"13 минут 17 секунд","lessonFormat":"video","sourceOrder":28,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='market-28aug';
